#[using="Type"] Theorem art_allocate_pre3a_16 : forall regs (M0 rom : word -> option byte) (raw : word) (sp ia n stk tp key tsd ctx t rl rs qr rz qz : Z),
  getr regs 1 = raw -> getr regs 2 = Z_to_bv 64 sp -> getr regs 4 = Z_to_bv 64 tp -> getr regs 10 = Z_to_bv 64 ia ->
  getr regs 11 = Z_to_bv 64 n -> getr regs 12 = Z_to_bv 64 16 -> getr regs 13 = Z_to_bv 64 stk -> getr regs 14 = Z_to_bv 64 1 -> getr regs 15 = Z_to_bv 64 1 ->
  (* [comment removed for export] *)
  1 <= n < 2 ^ 40 -> rl = AsanTab.rz_log n -> rz = 16 * 2 ^ rl -> rz = 16 * qz -> 1 <= qz <= 128 ->
  rs = (Z.max n 8 + 15) / 16 * 16 -> rs = 8 * qr -> Z.max n 8 <= rs <= Z.max n 8 + 15 -> rs + 16 + rz <= 65536 ->
  (* [comment removed for export] *)
  0x10007fff8000 + 4096 <= sp -> sp + 2144 <= 2 ^ 47 -> sp <= stk -> stk + 16 <= sp + 4096 ->
  0x10000 <= ia -> ia + 4096 <= 0x69c000 ->
  4096 <= t -> t + 4096 < 2 ^ 47 -> (t + 4096 <= 0x10000 \/ 0x69c000 <= t) -> apart t 4096 (sp - 1920) 6016 ->
  apart ctx 4096 (sp - 1920) 6016 -> (ctx + 4096 <= 0x10000 \/ 0x69c000 <= ctx) -> apart t 4096 ctx 4096 ->
  0x10100 <= tp -> tp + 8 <= 0x69c000 -> 0x10000 <= tsd -> tsd + 1024 <= 0x69c000 ->
  (* [comment removed for export] *)
  wrA M0 (sp - 1920) 1920 ->
  art_alloc_rodata M0 -> cellA M0 0x104d0 1 4 -> art_rz_rodata M0 -> art_tsd M0 tp key tsd ctx t ->
  cellA M0 0x146dd8 1 1 -> cellA M0 0x1c8362 1 0 -> cellA M0 (ia + 3616) 8 (2 ^ 40) -> cellA M0 (ia + 3624) 2 16 -> cellA M0 (ia + 3626) 2 2048 ->
  exists r5 (M5 : word -> option byte),
    msteps ASEGS (mkst regs (0x535f4 : word) M0 rom) (mkst r5 (0x57d4c : word) M5 rom)
    /\ getr r5 1 = (0x53894 : bv 64)%bv /\ getr r5 2 = Z_to_bv 64 (sp - 128) /\ getr r5 4 = Z_to_bv 64 tp /\ getr r5 8 = Z_to_bv 64 1 /\ getr r5 9 = Z_to_bv 64 n
    /\ getr r5 10 = Z_to_bv 64 ia /\ getr r5 11 = Z_to_bv 64 (t + 208) /\ getr r5 12 = Z_to_bv 64 (rs + 16 + rz) /\ getr r5 13 = Z_to_bv 64 8
    /\ getr r5 19 = Z_to_bv 64 (rs + 16 + rz) /\ getr r5 20 = Z_to_bv 64 rz /\ getr r5 21 = Z_to_bv 64 n /\ getr r5 22 = Z_to_bv 64 ia /\ getr r5 23 = Z_to_bv 64 stk
    /\ getr r5 25 = Z_to_bv 64 15 /\ getr r5 26 = Z_to_bv 64 t /\ getr r5 27 = Z_to_bv 64 1 /\ getr r5 3 = getr regs 3
    /\ mem_grows M0 M5
    /\ (forall x : word, ~ (sp - 144 <= U x < sp) -> M5 x = M0 x)
    /\ cellA M5 (sp - 128 + 120) 8 (U raw) /\ cellA M5 (sp - 128 + 112) 8 (U (getr regs 8)) /\ cellA M5 (sp - 128 + 104) 8 (U (getr regs 9))
    /\ cellA M5 (sp - 128 + 96) 8 (U (getr regs 18)) /\ cellA M5 (sp - 128 + 88) 8 (U (getr regs 19)) /\ cellA M5 (sp - 128 + 80) 8 (U (getr regs 20))
    /\ cellA M5 (sp - 128 + 72) 8 (U (getr regs 21)) /\ cellA M5 (sp - 128 + 64) 8 (U (getr regs 22)) /\ cellA M5 (sp - 128 + 56) 8 (U (getr regs 23))
    /\ cellA M5 (sp - 128 + 48) 8 (U (getr regs 24)) /\ cellA M5 (sp - 128 + 40) 8 (U (getr regs 25)) /\ cellA M5 (sp - 128 + 32) 8 (U (getr regs 26))
    /\ cellA M5 (sp - 128 + 24) 8 (U (getr regs 27)) /\ cellA M5 (sp - 128 + 8) 8 1 /\ cellA M5 (sp - 128 + 16) 8 32.
Proof.
